/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-14: flow layout: keep flow layout and wireStyle in the single-flow API
 *   E-01: deploy pipeline contract: readFlowsFromStorage(), load()/setFlows() with
 *   deployOpts and a preloaded config, build*FlowConfig(), start() returns errors;
 *   setFlows() keeps the deploy lock until the start completes (R-43)
 *   P-01: setFlows() with deployOpts.waitForStart resolves after the start and rejects
 *   with deploy_start_failed/deploy_stop_failed (with rev); deploy.startTimeout; a
 *   rejected start is logged in the default mode; start() reports safe_mode
 *   R-45: the deploy lock is released after deploy.startTimeout only with
 *   deploy.startTimeoutReleasesLock: true
 *   Z-04: getFlowRevision(); build*FlowConfig() create a flow under a given id, upsert
 *   globalConfigs and reject node ids of other flows
 *   E-02: start() reports its result to the instance state (runtime/lib/state.js)
 *   outside an operation, and returns flowsRunning: false with a reason when the
 *   flows were not started on purpose (safe mode, runtimeFlowState stop)
 *   Z-09: reloadFromStorage() (full or diff reload of a configuration read from
 *   storage, nothing saved, no forced start) and getChangedFlows()
 *   Z-15: editorOnly - the flows are loaded but never started (no runtimeFlowState,
 *   safe mode not cleared by a deployment), deployments only save
 *   Z-15: on an editor-only instance missing node types are a warning (state
 *   loaded, not failed) and checkFlowDependencies is not called
 *   #22: start_timeout reports the phase and the flows not started yet, flow_start_failed of a
 *   rejected start() the flow when known, the final result of a start that outlived the
 *   response limit is published as the runtime event deploy-start-result
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

const jsonClone = require("rfdc")();
const crypto = require("crypto");

var Flow = require('./Flow');

var typeRegistry = require("@node-red/registry");
var deprecated = typeRegistry.deprecated;

var context = require("../nodes/context")
var credentials = require("../nodes/credentials");
var flowUtil = require("./util");
const deployLock = require("./lock");
const instanceState = require("../state");
var log;
const events = require("@node-red/util").events;
var redUtil = require("@node-red/util").util;

var storage = null;
var settings = null;

// #22: the progress of the running start() - read when a deployment reports start_timeout.
// {phase: "modules"|"flows", startedAt, ids: [flow ids to start], index: position in ids, current}
let startProgress = null;

var activeConfig = null;
var activeFlowConfig = null;

var activeFlows = {};
var started = false;
var state = 'stop'

var credentialsPendingReset = false;

var activeNodesToFlow = {};

var typeEventRegistered = false;

function init(runtime) {
    if (started) {
        throw new Error("Cannot init without a stop");
    }
    settings = runtime.settings;
    storage = runtime.storage;
    log = runtime.log;
    started = false;
    state = 'stop';
    if (!typeEventRegistered) {
        events.on('type-registered',function(type) {
            if (activeFlowConfig && activeFlowConfig.missingTypes.length > 0) {
                var i = activeFlowConfig.missingTypes.indexOf(type);
                if (i != -1) {
                    log.info(log._("nodes.flows.registered-missing", {type:type}));
                    activeFlowConfig.missingTypes.splice(i,1);
                    if (activeFlowConfig.missingTypes.length === 0 && started) {
                        events.emit("runtime-event",{id:"runtime-state",retain: true});
                        start();
                    }
                }
            }
        });
        typeEventRegistered = true;
    }
    Flow.init(runtime);
    flowUtil.init(runtime);
    if (settings.editorOnly !== undefined && typeof settings.editorOnly !== "boolean") {
        // Z-15: only `true` enables the editor-only instance
        log.warn(log._("nodes.flows.editor-only-invalid", {value: String(settings.editorOnly)}));
    }
}

/**
 * Z-15 (R-19): an editor-only instance loads the flows and saves deployments,
 * but never starts the flows.
 * @return {boolean}
 */
function isEditorOnly() {
    return !!settings && settings.editorOnly === true;
}

/**
 * Reads the flow configuration from storage and loads its credentials
 * (E-01: the read step of a reload; the result can be deployed with
 * `load(forceStart, deployOpts, loaded)` without reading storage again).
 * @return {Promise<Object>} - the configuration `{flows, rev, credentials}`
 */
function readFlowsFromStorage() {
    var config;
    return storage.getFlows().then(function(_config) {
        config = _config;
        log.debug("loaded flow revision: "+config.rev);
        return credentials.load(config.credentials).then(function() {
            events.emit("runtime-event",{id:"runtime-state",retain:true});
            return config;
        });
    }).catch(function(err) {
        if (err.code === "credentials_load_failed" && !storage.projects) {
            // project disabled, credential load failed
            credentialsPendingReset = true;
            log.warn(log._("nodes.flows.error",{message:err.toString()}));
            events.emit("runtime-event",{id:"runtime-state",payload:{type:"warning",error:err.code,text:"notification.warnings.credentials_load_failed_reset"},retain:true});
            return config;
        } else {
            activeConfig = null;
            events.emit("runtime-event",{id:"runtime-state",payload:{type:"warning",error:err.code,project:err.project,text:"notification.warnings."+err.code},retain:true});
            if (err.code === "project_not_found") {
                log.warn(log._("storage.localfilesystem.projects.project-not-found",{project:err.project}));
            } else {
                log.warn(log._("nodes.flows.error",{message:err.toString()}));
            }
            throw err;
        }
    });
}
/**
 * Loads the flow configuration from storage and (re)starts it.
 * @param {boolean} forceStart - start the flows even if they are not running (reload)
 * @param {DeployOpts} [deployOpts] - internal deploy options (E-01); omitted for the default behaviour
 * @param {Object} [loaded] - a configuration already read by readFlowsFromStorage();
 *     when given, storage is not read again
 * @return {Promise<String>} - the revision of the loaded flows
 */
function load(forceStart, deployOpts, loaded) {
    if (forceStart && settings.safeMode && !isEditorOnly()) {
        // This is a force reload from the API - disable safeMode
        delete settings.safeMode;
    }
    return setFlows(null,null,"load",false,forceStart,undefined,deployOpts,loaded);
}

/**
 * Reloads a configuration read from storage (Z-09, contract E-01 part B step 5,
 * called by the deploy pipeline under the deploy lock): the credentials are
 * loaded, the flows stopped and started according to `opts.type` - nothing is
 * saved and stopped flows (idle) are not started.
 * @param {Object} loaded - `{flows, rev, credentials}` from storage.getFlows()
 * @param {Object} [opts]
 * @param {"full"|"diff"} [opts.type="full"] - "diff": only the changed flows
 *     (a changed global configuration restarts all)
 * @return {Promise<String>} - the revision of the reloaded flows
 */
async function reloadFromStorage(loaded, opts) {
    opts = opts || {};
    await credentials.load(loaded.credentials || {});
    return setFlows(null,null,"load",false,false,undefined,{reloadType: opts.type === "diff" ? "diff" : "full"},loaded);
}

/**
 * The flows (tabs and subflows) a configuration read from storage changes
 * compared with the active one (Z-09, payload `changedFlows` of preReload).
 * @param {Object} loaded - `{flows}`
 * @return {String[]|null} - the ids, sorted; null when all flows restart (a
 *     changed global configuration or no active configuration)
 */
function getChangedFlows(loaded) {
    if (!activeFlowConfig) {
        return null;
    }
    const newConfig = flowUtil.parseConfig(jsonClone((loaded && loaded.flows) || []));
    const diff = flowUtil.diffConfigs(activeFlowConfig, newConfig);
    if (diff.globalConfigChanged) {
        return null;
    }
    const ids = new Set(diff.flowChanged);
    const nodeIds = diff.added.concat(diff.changed, diff.removed, diff.rewired, diff.linked);
    for (const id of nodeIds) {
        const node = newConfig.allNodes[id] || activeFlowConfig.allNodes[id];
        if (node && node.z) {
            ids.add(node.z);
        } else if ((node && (node.type === "tab" || node.type === "subflow")) || newConfig.flows[id] || activeFlowConfig.flows[id]) {
            ids.add(id);
        } else if (node) {
            // A config node outside the flows: all flows may use it
            return null;
        }
    }
    return Array.from(ids).sort();
}

/*
 * _config - new node array configuration
 * _credentials - new credentials configuration (optional)
 * type - full/nodes/flows/load (default full)
 * muteLog - don't emit the standard log messages (used for individual flow api)
 * forceStart - start the flows even if they are not running
 * user - the user making the change (passed to storage)
 * deployOpts - internal deploy options (E-01, typedef DeployOpts in flows/pipeline.js):
 *     `{waitForStart: boolean}`. Passed by the runtime api for Admin API deployments
 *     (P-01, deploy.response "started"); internal calls (runtime start, projects)
 *     never pass it. With waitForStart the promise resolves after the start and the
 *     runtime-deploy event, or rejects with code "deploy_start_failed" (status 500,
 *     rev, errors[]) or "deploy_stop_failed" (status 500, rev).
 * loaded - type "load" only: the configuration already read from storage
 *     (readFlowsFromStorage), deployed without reading storage again
 */
function setFlows(_config,_credentials,type,muteLog,forceStart,user,deployOpts,loaded) {
    if (typeof _credentials === "string") {
        type = _credentials;
        _credentials = null;
    }
    type = type||"full";
    // Z-15: on an editor-only instance a deployment does not end the safe mode
    if (settings.safeMode && !isEditorOnly()) {
        if (type !== "load") {
            // If in safeMode, the flows are stopped. We cannot do a modified nodes/flows
            // type deploy as nothing is running. Can only do a "load" or "full" deploy.
            // The "load" case is already handled in `load()` to distinguish between
            // startup-load and api-request-load.
            type = "full";
            delete settings.safeMode;
        }
    }

    var configSavePromise = null;
    var config = null;
    var diff;
    var newFlowConfig;
    var isLoad = false;
    if (type === "load") {
        isLoad = true;
        configSavePromise = (loaded ? Promise.resolve(loaded) : readFlowsFromStorage()).then(function(_config) {
            config = jsonClone(_config.flows);
            newFlowConfig = flowUtil.parseConfig(jsonClone(config));
            if (deployOpts && deployOpts.reloadType === "diff" && activeFlowConfig) {
                // Z-09: a diff reload restarts only the changed flows
                diff = flowUtil.diffConfigs(activeFlowConfig,newFlowConfig);
                type = "flows";
            } else {
                type = "full";
            }
            return _config.rev;
        });
    } else {
        // Clone the provided config so it can be manipulated
        config = jsonClone(_config);
        // Parse the configuration
        newFlowConfig = flowUtil.parseConfig(jsonClone(config));
        // Generate a diff to identify what has changed
        diff = flowUtil.diffConfigs(activeFlowConfig,newFlowConfig);

        // Now the flows have been compared, remove any credentials from newFlowConfig
        // so they don't cause false-positive diffs the next time a flow is deployed
        for (var id in newFlowConfig.allNodes) {
            if (newFlowConfig.allNodes.hasOwnProperty(id)) {
                delete newFlowConfig.allNodes[id].credentials;
            }
        }
        var credsDirty;

        if (_credentials) {
            if (_credentials['$']) {
                // this is a set of encrypted credentials - pass to load to decrypt
                // the complete set
                configSavePromise = credentials.load(_credentials);
            } else {
                credentials.clean(config);
                // A full set of credentials have been provided. Use those instead
                let credentialSavePromises = [];
                for (let id in _credentials) {
                    if (_credentials.hasOwnProperty(id)) {
                        credentialSavePromises.push(credentials.add(id,_credentials[id]));
                    }
                }
                configSavePromise = Promise.all(credentialSavePromises);
                credsDirty = true;
            }
        } else {
            // Allow the credential store to remove anything no longer needed
            credentials.clean(config);

            // Remember whether credentials need saving or not
            var credsDirty = credentials.dirty();

            configSavePromise = Promise.resolve();
        }

        // Get the latest credentials and ask storage to save them (if needed)
        // as well as the new flow configuration.
        configSavePromise = configSavePromise.then(function() {
            return credentials.export()
        }).then(function(creds) {
            var saveConfig = {
                flows: config,
                credentialsDirty:credsDirty,
                credentials: creds
            }
            return storage.saveFlows(saveConfig, user);
        });
    }


    return configSavePromise.then(flowRevision => {
        if (!isLoad) {
            log.debug("saved flow revision: "+flowRevision);
        }
        activeConfig = {
            flows:config,
            rev:flowRevision
        };
        activeFlowConfig = newFlowConfig;
        // Z-15: an editor-only instance never stops or starts nodes (steps 6-7
        // skipped): the deployment is saved and runtime-deploy emitted below
        if ((forceStart || started) && !isEditorOnly()) {
            // Flows are running (or should be)

            const waitForStart = !!(deployOpts && deployOpts.waitForStart);
            const startTimeout = getStartTimeout();
            // Stop the active flows (according to deploy type and the diff)
            const stopped = stop(type,diff,muteLog,true).then(() => {
                // Once stopped, allow context to remove anything no longer needed
                return context.clean(activeFlowConfig)
            });
            const startFlows = () => {
                if (!isLoad) {
                    log.info(log._("nodes.flows.updated-flows"));
                }
                // Start the active flows
                const startPromise = start(type,diff,muteLog,true);
                // Under the deploy lock (deployment, project switch) the lock is
                // held until the start completes (E-01 step 8, R-43, R-45) - at most
                // until deploy.startTimeout has passed only with
                // deploy.startTimeoutReleasesLock: true (P-01)
                deployLock.holdUntil(startPromise, getStartTimeoutReleasesLock() ? {limit: startTimeout} : undefined);
                return startPromise.then(result => {
                    events.emit("runtime-event",{id:"runtime-deploy",payload:{revision:flowRevision},retain: true});
                    return result;
                });
            };
            if (!waitForStart) {
                return stopped.then(() => {
                    startFlows().catch(err => {
                        // P-01 (R-10): a rejected start is logged instead of an
                        // unhandled rejection; the response is unchanged
                        log.error(log._("nodes.flows.start-failed", {message: (err && err.message) || String(err)}));
                        log.debug(err && err.stack);
                    });
                    // Return the new revision asynchronously to the actual start
                    return flowRevision;
                }).catch(function(err) { })
            }
            // P-01: deploy.response "started" - resolve once the new flows have
            // started and runtime-deploy is emitted (steps 7-9); stop errors
            // are reported (D-05) and start errors reject with the revision
            return stopped.then(() => {
                return waitForDeployStart(startFlows(), flowRevision, startTimeout);
            }, err => {
                throw deployError("deploy_stop_failed", (err && err.message) || String(err), flowRevision);
            });
        } else {
            if (!isLoad) {
                log.info(log._("nodes.flows.updated-flows"));
            }
            events.emit("runtime-event",{id:"runtime-deploy",payload:{revision:flowRevision},retain: true});
            return flowRevision;
        }
    });
}

/**
 * The limit for the start of the flows of a deployment (P-01, R-38):
 * `deploy.startTimeout` in ms, or undefined when not set (disabled).
 * @return {number|undefined}
 */
function getStartTimeout() {
    const deploySettings = settings && settings.deploy;
    if (deploySettings && typeof deploySettings.startTimeout === "number" && deploySettings.startTimeout > 0) {
        return deploySettings.startTimeout;
    }
    return undefined;
}

/**
 * Whether the deploy lock is released when `deploy.startTimeout` has passed
 * while the flows are still starting (R-45): only with
 * `deploy.startTimeoutReleasesLock: true` and a start timeout. By default the
 * lock is kept until the start completes (R-43).
 * @return {boolean}
 */
function getStartTimeoutReleasesLock() {
    const deploySettings = settings && settings.deploy;
    return !!(deploySettings && deploySettings.startTimeoutReleasesLock === true && getStartTimeout());
}

/**
 * Creates the error of a deployment whose configuration has been saved (P-01):
 * `{code, message, status: 500, rev, errors?}`.
 */
function deployError(code, message, rev, errors) {
    const err = new Error(message);
    err.code = code;
    err.status = 500;
    err.rev = rev;
    if (errors) {
        err.errors = errors;
    }
    return err;
}

/**
 * Waits for the start of the flows of a deployment (P-01, deploy.response "started").
 * Resolves with the revision when the flows started without errors; rejects with
 * `deploy_start_failed` (with `rev` and `errors[]`) when the start reported errors,
 * failed, or did not complete within `startTimeout` - the start then goes on in
 * the background and its result is logged (R-38).
 * @param {Promise<{errors: Array}>} started - the start (resolves after runtime-deploy)
 * @param {String} rev - the revision of the deployed configuration
 * @param {number} [startTimeout] - the limit in ms
 * @return {Promise<String>}
 */
function waitForDeployStart(started, rev, startTimeout) {
    const failed = function(errors) {
        return deployError("deploy_start_failed", log._("nodes.flows.deploy-start-failed"), rev, errors);
    };
    const result = started.then(function(startResult) {
        const errors = (startResult && startResult.errors) || [];
        if (errors.length > 0) {
            throw failed(errors);
        }
        return rev;
    }, function(err) {
        const entry = {code: "flow_start_failed", message: (err && err.message) || String(err)};
        // #22: the flow, when the start knew which one failed
        if (err && err.flow !== undefined) {
            entry.flow = err.flow;
        }
        throw failed([entry]);
    });
    if (!startTimeout) {
        return result;
    }
    return new Promise(function(resolve, reject) {
        let timedOut = false;
        const timer = setTimeout(function() {
            timedOut = true;
            // #22: facts about the start that goes on (additive fields)
            const timeoutError = {code: "start_timeout", message: log._("nodes.flows.start-timeout", {timeout: startTimeout}), timeout: startTimeout};
            Object.assign(timeoutError, getStartProgress());
            reject(failed([timeoutError]));
            // The flows keep starting in the background: log the result and
            // tell the editor (#22, only after a start_timeout response)
            result.then(function() {
                log.info(log._("nodes.flows.started-after-timeout", {rev: rev}));
                events.emit("runtime-event",{id:"deploy-start-result",payload:{type:"success",text:"notification.info.deploy-started",timeout:8000,revision:rev},retain:false});
            }, function(err) {
                log.warn(log._("nodes.flows.start-failed-after-timeout", {rev: rev, errors: JSON.stringify(err.errors || err.message)}));
                events.emit("runtime-event",{id:"deploy-start-result",payload:{type:"error",error:"deploy_start_failed",text:"notification.errors.deploy-start-failed",revision:rev,errors:err.errors||[{code:"flow_start_failed",message:(err&&err.message)||String(err)}]},retain:false});
            });
        }, startTimeout);
        result.then(function(value) {
            if (!timedOut) {
                clearTimeout(timer);
                resolve(value);
            }
        }, function(err) {
            if (!timedOut) {
                clearTimeout(timer);
                reject(err);
            }
        });
    });
}

function getNode(id) {
    var node;
    if (activeNodesToFlow[id] && activeFlows[activeNodesToFlow[id]]) {
        return activeFlows[activeNodesToFlow[id]].getNode(id,true);
    }
    for (var flowId in activeFlows) {
        if (activeFlows.hasOwnProperty(flowId)) {
            node = activeFlows[flowId].getNode(id,true);
            if (node) {
                return node;
            }
        }
    }
    return null;
}

function eachNode(cb) {
    for (var id in activeFlowConfig.allNodes) {
        if (activeFlowConfig.allNodes.hasOwnProperty(id)) {
            cb(activeFlowConfig.allNodes[id]);
        }
    }
}

function getFlows() {
    return activeConfig;
}

/**
 * Starts the active flow configuration.
 * Errors are logged and reported with runtime-state events as before; they are
 * also returned (E-01) so a deployment can report them (P-01). Callers that
 * ignore the result see no change.
 *
 * E-02: when the flows are not started on purpose the result also has
 * `flowsRunning: false` and `reason` ("safe-mode" | "set-state"). Outside an
 * operation of the instance state (first start, late start after a missing
 * type was registered, project switch) the result is reported to the
 * instance state; during a deployment or `POST /flows/state` the operation
 * sets the state when it ends.
 * @return {Promise<{errors: Array<{code: String, message: String, flow?: String, types?: Array, modules?: Array}>, flowsRunning?: boolean, reason?: String}>}
 *     `code`: "missing_types" | "missing_modules" | "flow_start_failed" | "safe_mode" (P-01)
 */
async function start(type,diff,muteLog,isDeploy) {
    let result;
    const progress = { phase: "modules", startedAt: Date.now(), ids: [], index: 0, current: undefined };
    startProgress = progress;
    try {
        result = await startActiveFlows(type,diff,muteLog,isDeploy,progress);
    } catch (err) {
        instanceState.fail(err, "flow-start-failed");
        // #22: the flow being created or started when the start failed, for the deployment error
        if (progress.current !== undefined && err && typeof err === "object" && Object.isExtensible(err) && err.flow === undefined) {
            err.flow = progress.current;
        }
        throw err;
    } finally {
        if (startProgress === progress) {
            startProgress = null;
        }
    }
    instanceState.report(result);
    return result;
}

/**
 * #22: facts about the running start() for the start_timeout error of a deployment:
 * `phase` ("modules" while the modules of the flows are checked and installed, "flows"
 * while the flows start), `startedAt` (ms since epoch), `elapsed` (ms), `pending` (ids of
 * the flows not started yet, including `current`) and `current` (the flow being started;
 * present only while a flow of `pending` is being started - not while the start waits for a
 * flow that this deployment does not start anything in).
 * @return {Object|null} null when no start is running
 */
function getStartProgress() {
    const progress = startProgress;
    if (!progress) {
        return null;
    }
    const facts = {
        phase: progress.phase,
        startedAt: progress.startedAt,
        elapsed: Date.now() - progress.startedAt,
        pending: progress.ids.slice(progress.index)
    };
    if (progress.phase === "flows" && progress.processing !== undefined && progress.ids[progress.index] === progress.processing) {
        facts.current = progress.processing;
    }
    return facts;
}

/**
 * #22: the ids of the active flows (and "global") whose start does something in this
 * start, in start order: all of them for a full start; for a modified-flows/nodes
 * start only the flows created by it and those that hold a node the start creates (added,
 * changed; with "flows" also rewired and linked - the stop of a "nodes" deployment leaves
 * those nodes running and the start only rewires them) or whose own properties changed
 * (`flowChanged`) - the other flows keep running and are not started again.
 * @param {String} type - the type of the start (after a changed global configuration "full")
 * @param {Object} [diff] - the diff of the deployment
 * @param {Set<String>} alreadyActive - the ids of the flows that were active before the start
 * @return {String[]}
 */
function getFlowsToStart(type, diff, alreadyActive) {
    const active = Object.keys(activeFlows);
    if (type === "full" || !diff) {
        return active;
    }
    const touched = new Set();
    active.forEach(function(id) {
        if (!alreadyActive.has(id)) {
            touched.add(id);
        }
    });
    (diff.flowChanged || []).forEach(function(id) { touched.add(id) });
    const nodeIds = type === "flows"
        ? [].concat(diff.added || [], diff.changed || [], diff.rewired || [], diff.linked || [])
        : [].concat(diff.added || [], diff.changed || []);
    nodeIds.forEach(function(nid) {
        const node = activeFlowConfig.allNodes[nid];
        if (!node) {
            return;
        }
        if (node.z) {
            touched.add(node.z);
        } else if (node.type !== "tab" && node.type !== "subflow") {
            // a configuration node outside the flows belongs to the global flow
            touched.add("global");
        }
        // (a tab or subflow id in the diff - the deployment lists the flow of a rewired node as
        // changed - starts nothing by itself: the flows it changes are in `flowChanged`)
    });
    return active.filter(function(id) { return touched.has(id) });
}

async function startActiveFlows(type,diff,muteLog,isDeploy,progress) {
    const result = { errors: [] };
    type = type || "full";
    if (diff && diff.globalConfigChanged) {
        type = 'full'
    }

    started = true;
    state = 'start'
    var i;

    // Z-15: an editor-only instance never starts the flows and does not read
    // runtimeFlowState (the state of the flows of other instances). Missing node
    // types are only a warning (the instance stays "loaded" - the editor still
    // works) and the modules of the function node are not installed
    // (checkFlowDependencies is not called)
    if (isEditorOnly()) {
        if (activeFlowConfig.missingTypes.length > 0) {
            log.warn(log._("nodes.flows.editor-only-missing-types", {types: activeFlowConfig.missingTypes.join(", ")}));
        }
        log.info(log._("nodes.flows.editor-only"));
        events.emit("runtime-event",{id:"runtime-state",payload:{state: 'stop', error:"editor-only", type:"info", text:"notification.info.editor-only"},retain:true});
        state = 'stop';
        started = false;
        result.flowsRunning = false;
        result.reason = "editor-only";
        return result;
    }

    // If there are missing types, report them, emit the necessary runtime event and return
    if (activeFlowConfig.missingTypes.length > 0) {
        log.info(log._("nodes.flows.missing-types"));
        var knownUnknowns = 0;
        for (i=0;i<activeFlowConfig.missingTypes.length;i++) {
            var nodeType = activeFlowConfig.missingTypes[i];
            var info = deprecated.get(nodeType);
            if (info) {
                log.info(log._("nodes.flows.missing-type-provided",{type:activeFlowConfig.missingTypes[i],module:info.module}));
                knownUnknowns += 1;
            } else {
                log.info(" - "+activeFlowConfig.missingTypes[i]);
            }
        }
        if (knownUnknowns > 0) {
            log.info(log._("nodes.flows.missing-type-install-1"));
            log.info("  npm install <module name>");
            log.info(log._("nodes.flows.missing-type-install-2"));
            log.info("  "+settings.userDir);
        }
        events.emit("runtime-event",{id:"runtime-state",payload:{state: 'stop', error:"missing-types", type:"warning",text:"notification.warnings.missing-types",types:activeFlowConfig.missingTypes},retain:true});
        result.errors.push({code: "missing_types", message: "Missing node types", types: activeFlowConfig.missingTypes.slice()});
        return result;
    }

    try {
        await typeRegistry.checkFlowDependencies(activeConfig.flows);
    } catch(err) {
        log.info("Failed to load external modules required by this flow:");
        const missingModules = [];
        for (i=0;i<err.length;i++) {
            let errMessage = err[i].error.toString()
            missingModules.push({module:err[i].module.module, error: err[i].error.code || err[i].error.toString()})
            log.info(` - ${err[i].module.spec} [${err[i].error.code || "unknown_error"}]`);
        }
        events.emit("runtime-event",{id:"runtime-state",payload:{state: 'stop', error:"missing-modules", type:"warning",text:"notification.warnings.missing-modules",modules:missingModules},retain:true});
        result.errors.push({code: "missing_modules", message: "Missing modules", modules: missingModules});
        return result;
    }

    // In safe mode, don't actually start anything, emit the necessary runtime event and return
    if (settings.safeMode) {
        log.info("*****************************************************************")
        log.info(log._("nodes.flows.safe-mode"));
        log.info("*****************************************************************")
        state = 'safe'
        events.emit("runtime-event",{id:"runtime-state",payload:{state: 'safe', error:"safe-mode", type:"warning",text:"notification.warnings.safe-mode"},retain:true});
        // P-01 (R-10, R-33): the flows were not started - reported to a deployment
        result.errors.push({code: "safe_mode", message: "Flows not started in safe mode"});
        // E-02: not started on purpose - the instance state is "idle"
        result.flowsRunning = false;
        result.reason = "safe-mode";
        return result;
    }

    let runtimeState
    try {
        runtimeState = settings.get('runtimeFlowState') || 'start'
    } catch (err) {}
    if (runtimeState === 'stop') {
        log.info(log._("nodes.flows.stopped-flows"));
        events.emit("runtime-event",{id:"runtime-state",payload:{ state: 'stop', deploy:isDeploy },retain:true});
        state = 'stop'
        started = false
        // E-02: not started on purpose - the instance state is "idle"
        result.flowsRunning = false;
        result.reason = "set-state";
        return result
    }

    if (!muteLog) {
        if (type !== "full") {
            log.info(log._("nodes.flows.starting-modified-"+type));
        } else {
            log.info(log._("nodes.flows.starting-flows"));
        }
    }

    events.emit("flows:starting", {config: activeConfig, type: type, diff: diff})

    var id;
    // #22: the flows that existed before this start - the others are created by it
    const alreadyActive = new Set(Object.keys(activeFlows));
    if (type === "full") {
        // A full start means everything should

        // Check the 'global' flow is running
        if (!activeFlows['global']) {
            log.debug("red/nodes/flows.start : starting flow : global");
            progress.current = "global";
            activeFlows['global'] = Flow.create(flowAPI,activeFlowConfig);
        }

        // Check each flow in the active configuration
        for (id in activeFlowConfig.flows) {
            if (activeFlowConfig.flows.hasOwnProperty(id)) {
                progress.current = id;
                if (!activeFlowConfig.flows[id].disabled && !activeFlows[id]) {
                    // This flow is not disabled, nor is it currently active, so create it
                    activeFlows[id] = Flow.create(activeFlows['global'],activeFlowConfig,activeFlowConfig.flows[id]);
                    log.debug("red/nodes/flows.start : starting flow : "+id);
                } else {
                    log.debug("red/nodes/flows.start : not starting disabled flow : "+id);
                }
            }
        }
    } else {
        // A modified-type deploy means restarting things that have changed

        // Update the global flow
        progress.current = "global";
        if (activeFlows['global']) {
            activeFlows['global'].update(activeFlowConfig,activeFlowConfig);
        } else {
            log.debug("red/nodes/flows.start : starting flow : global");
            activeFlows['global'] = Flow.create(flowAPI,activeFlowConfig);
        }
        for (id in activeFlowConfig.flows) {
            if (activeFlowConfig.flows.hasOwnProperty(id)) {
                progress.current = id;
                if (!activeFlowConfig.flows[id].disabled) {
                    if (activeFlows[id]) {
                        // This flow exists and is not disabled, so update it
                        activeFlows[id].update(activeFlowConfig,activeFlowConfig.flows[id]);
                    } else {
                        // This flow didn't previously exist, so create it
                        activeFlows[id] = Flow.create(activeFlows['global'],activeFlowConfig,activeFlowConfig.flows[id]);
                        log.debug("red/nodes/flows.start : starting flow : "+id);
                    }
                } else {
                    log.debug("red/nodes/flows.start : not starting disabled flow : "+id);
                }
            }
        }
    }
    // #22: from here on the flows start one by one
    progress.phase = "flows";
    progress.ids = getFlowsToStart(type, diff, alreadyActive);
    progress.index = 0;
    progress.current = undefined;
    progress.processing = undefined;
    for (id in activeFlows) {
        if (activeFlows.hasOwnProperty(id)) {
            // the flow the start is working on; `current` of a start_timeout is only a flow of ids
            progress.processing = id;
            try {
                await activeFlows[id].start(diff);
                // Create a map of node id to flow id and also a subflowInstance lookup map
                var activeNodes = activeFlows[id].getActiveNodes();
                Object.keys(activeNodes).forEach(function(nid) {
                    activeNodesToFlow[nid] = id;
                });
            } catch(err) {
                console.log(err.stack);
                result.errors.push({code: "flow_start_failed", message: err.message || String(err), flow: id});
            }
            if (progress.ids[progress.index] === id) {
                progress.index += 1;
            }
        }
    }
    events.emit("flows:started", {config: activeConfig, type: type, diff: diff});
    // Deprecated event
    events.emit("nodes-started");

    if (credentialsPendingReset === true) {
        credentialsPendingReset = false;
    } else {
        events.emit("runtime-event",{id:"runtime-state", payload:{ state: 'start', deploy:isDeploy}, retain:true});
    }

    if (!muteLog) {
        if (type !== "full") {
            log.info(log._("nodes.flows.started-modified-"+type));
        } else {
            log.info(log._("nodes.flows.started-flows"));
        }
    }
    return result;
}

function stop(type,diff,muteLog,isDeploy) {
    if (!started) {
        return Promise.resolve();
    }
    type = type||"full";
    diff = diff||{
        added:[],
        changed:[],
        removed:[],
        rewired:[],
        linked:[],
        flowChanged:[]
    };
    if (!muteLog) {
        if (type !== "full") {
            log.info(log._("nodes.flows.stopping-modified-"+type));
        } else {
            log.info(log._("nodes.flows.stopping-flows"));
        }
    }
    if (diff.globalConfigChanged) {
        type = 'full'
    }
    started = false;
    state = 'stop'
    var promises = [];
    var stopList;
    var removedList = diff.removed;
    if (type === 'nodes') {
        stopList = diff.changed.concat(diff.removed);
    } else if (type === 'flows') {
        stopList = diff.changed.concat(diff.removed).concat(diff.linked).concat(diff.rewired);
    }
    events.emit("flows:stopping",{config: activeConfig, type: type, diff: diff})

    // Stop the global flow object last
    let activeFlowIds = Object.keys(activeFlows);
    let globalIndex = activeFlowIds.indexOf("global");
    if (globalIndex !== -1) {
        activeFlowIds.splice(globalIndex,1);
        activeFlowIds.push("global");
    }

    activeFlowIds.forEach(id => {
        if (activeFlows.hasOwnProperty(id)) {
            var flowStateChanged = diff && (diff.flowChanged.indexOf(id) !== -1 || diff.added.indexOf(id) !== -1 || diff.removed.indexOf(id) !== -1);
            log.debug("red/nodes/flows.stop : stopping flow : "+id);
            promises.push(activeFlows[id].stop(flowStateChanged?null:stopList,removedList));
            if (type === "full" || flowStateChanged || diff.removed.indexOf(id)!==-1) {
                delete activeFlows[id];
            }
        }
    });

    return Promise.all(promises).then(function() {
        for (let id in activeNodesToFlow) {
            if (activeNodesToFlow.hasOwnProperty(id)) {
                if (!activeFlows[activeNodesToFlow[id]]) {
                    delete activeNodesToFlow[id];
                }
            }
        }
        if (stopList) {
            stopList.forEach(function(id) {
                delete activeNodesToFlow[id];
            });
        }
        if (!muteLog) {
            if (type !== "full") {
                log.info(log._("nodes.flows.stopped-modified-"+type));
            } else {
                log.info(log._("nodes.flows.stopped-flows"));
            }
        }
        events.emit("flows:stopped",{config: activeConfig, type: type, diff: diff});

        events.emit("runtime-event",{ id:"runtime-state", payload:{ state: 'stop', deploy:isDeploy }, retain:true });
        // Deprecated event
        events.emit("nodes-stopped");
    });
}


function checkTypeInUse(id) {
    var nodeInfo = typeRegistry.getNodeInfo(id);
    if (!nodeInfo) {
        throw new Error(log._("nodes.index.unrecognised-id", {id:id}));
    } else {
        var inUse = {};
        var config = getFlows();
        config.flows.forEach(function(n) {
            inUse[n.type] = (inUse[n.type]||0)+1;
        });
        var nodesInUse = [];
        nodeInfo.types.forEach(function(t) {
            if (inUse[t]) {
                nodesInUse.push(t);
            }
        });
        if (nodesInUse.length > 0) {
            var msg = nodesInUse.join(", ");
            var err = new Error(log._("nodes.index.type-in-use", {msg:msg}));
            err.code = "type_in_use";
            throw err;
        }
    }
}

function updateMissingTypes() {
    var subflowInstanceRE = /^subflow:(.+)$/;
    activeFlowConfig.missingTypes = [];

    for (var id in activeFlowConfig.allNodes) {
        if (activeFlowConfig.allNodes.hasOwnProperty(id)) {
            var node = activeFlowConfig.allNodes[id];
            if (node.type !== 'tab' && node.type !== 'subflow') {
                var subflowDetails = subflowInstanceRE.exec(node.type);
                if ( (subflowDetails && !activeFlowConfig.subflows[subflowDetails[1]]) || (!subflowDetails && !typeRegistry.get(node.type)) ) {
                    if (activeFlowConfig.missingTypes.indexOf(node.type) === -1) {
                        activeFlowConfig.missingTypes.push(node.type);
                    }
                }
            }
        }
    }
}

// Editor layout options of a flow that are passed through the single-flow API
const FLOW_LAYOUT_PROPERTIES = ['layout', 'wireStyle'];

function copyFlowLayoutProperties(source, target) {
    FLOW_LAYOUT_PROPERTIES.forEach(function(prop) {
        if (source.hasOwnProperty(prop)) {
            target[prop] = source[prop];
        }
    });
}

/**
 * Builds the tab node of a flow from the single-flow api
 * (with the flow layout properties - FL-B-001).
 */
function buildTabNode(id, flow) {
    var tabNode = {
        type:'tab',
        label:flow.label,
        id:id
    }
    if (flow.hasOwnProperty('info')) {
        tabNode.info = flow.info;
    }
    if (flow.hasOwnProperty('disabled')) {
        tabNode.disabled = flow.disabled;
    }
    if (flow.hasOwnProperty('env')) {
        tabNode.env = flow.env;
    }
    copyFlowLayoutProperties(flow, tabNode);
    return tabNode;
}

/**
 * Builds the full configuration that adds `flow` to the active configuration
 * (E-01: the configuration deployed by addFlow, without deploying it).
 * Assigns a new id to `flow` (`flow.id`) and sets `z` of its nodes, as addFlow does.
 * @param {Object} flow - the flow: `{label, info?, disabled?, env?, layout?, wireStyle?, nodes: [], configs?: []}`
 * @param {Object} [opts]
 * @param {Array} [opts.globalConfigs] - global configuration nodes to add or replace (Z-04)
 * @return {{config: Array, id: String}} - the new configuration and the id of the new flow
 * @throws {Error} 'missing nodes property', 'duplicate id', 'invalid node type: <type>';
 *     for globalConfigs errors with code "duplicate_id" / "invalid_node_type"
 */
function buildAddFlowConfig(flow, opts) {
    var i,node;
    if (!flow.hasOwnProperty('nodes')) {
        throw new Error('missing nodes property');
    }
    flow.id = redUtil.generateId();

    var tabNode = buildTabNode(flow.id, flow);

    var nodes = [tabNode];

    for (i=0;i<flow.nodes.length;i++) {
        node = flow.nodes[i];
        if (activeFlowConfig.allNodes[node.id]) {
            // TODO nls
            throw new Error('duplicate id');
        }
        if (node.type === 'tab' || node.type === 'subflow') {
            throw new Error('invalid node type: '+node.type);
        }
        node.z = flow.id;
        nodes.push(node);
    }
    if (flow.configs) {
        for (i=0;i<flow.configs.length;i++) {
            node = flow.configs[i];
            if (activeFlowConfig.allNodes[node.id]) {
                // TODO nls
                throw new Error('duplicate id');
            }
            if (node.type === 'tab' || node.type === 'subflow') {
                throw new Error('invalid node type: '+node.type);
            }
            node.z = flow.id;
            nodes.push(node);
        }
    }
    var newConfig = jsonClone(activeConfig.flows);
    newConfig = newConfig.concat(nodes);
    if (opts && opts.globalConfigs) {
        newConfig = applyGlobalConfigs(newConfig, opts.globalConfigs);
    }
    return { config: newConfig, id: flow.id };
}

function flowError(code, message) {
    const err = new Error(message);
    err.code = code;
    return err;
}

/**
 * Adds or replaces global configuration nodes (no `z`) in a configuration (Z-04).
 * A node with the id of a node that belongs to a flow or subflow is rejected
 * (`duplicate_id`), as are nodes of type tab, subflow and group (`invalid_node_type`).
 * @param {Array} config - the new configuration (modified)
 * @param {Array} globalConfigs - the global configuration nodes
 * @return {Array} the configuration
 */
function applyGlobalConfigs(config, globalConfigs) {
    if (!Array.isArray(globalConfigs)) {
        throw flowError("invalid_request", "globalConfigs must be an array");
    }
    globalConfigs.forEach(function(globalConfig) {
        if (!globalConfig || typeof globalConfig !== "object" || !globalConfig.id) {
            throw flowError("invalid_request", "globalConfigs must contain nodes with an id");
        }
        if (globalConfig.type === 'tab' || globalConfig.type === 'subflow' || globalConfig.type === 'group') {
            throw flowError("invalid_node_type", "invalid global configuration node type: "+globalConfig.type+" ("+globalConfig.id+")");
        }
        const node = jsonClone(globalConfig);
        delete node.z;
        const index = config.findIndex(n => n.id === node.id);
        if (index === -1) {
            config.push(node);
        } else if (config[index].z || config[index].type === 'tab' || config[index].type === 'subflow') {
            throw flowError("duplicate_id", "duplicate id: "+node.id+" is used in flow "+(config[index].z || config[index].id));
        } else {
            config[index] = node;
        }
    });
    return config;
}

/**
 * The revision of a single flow (Z-04): sha256 of the JSON of the tab node and
 * the nodes with `z` equal to the flow id (in the order of the configuration,
 * without credentials). For `global`: the nodes without `z` (except tabs), the
 * subflow definitions and their nodes.
 * @param {String} id - the flow id, or "global"
 * @return {String|null} - the revision, or null if the flow does not exist
 */
function getFlowRevision(id) {
    if (!activeConfig || !activeConfig.flows) {
        return null;
    }
    const all = activeConfig.flows;
    let nodes;
    if (id === 'global') {
        const subflows = {};
        all.forEach(function(n) { if (n.type === 'subflow') { subflows[n.id] = true } });
        nodes = all.filter(n => n.type !== 'tab' && (!n.z || subflows[n.z]));
    } else {
        if (!all.some(n => n.id === id && n.type === 'tab')) {
            return null;
        }
        nodes = all.filter(n => (n.id === id && n.type === 'tab') || n.z === id);
    }
    nodes = nodes.map(function(n) {
        const node = Object.assign({}, n);
        delete node.credentials;
        return node;
    });
    return crypto.createHash('sha256').update(JSON.stringify(nodes)).digest("hex");
}

async function addFlow(flow, user, deployOpts, opts) {
    var built = buildAddFlowConfig(flow, opts);
    return setFlows(built.config, null, 'flows', true, null, user, deployOpts).then(function() {
        log.info(log._("nodes.flows.added-flow",{label:(flow.label?flow.label+" ":"")+"["+flow.id+"]"}));
        return flow.id;
    });
}

function getFlow(id) {
    var flow;
    if (id === 'global') {
        flow = activeFlowConfig;
    } else {
        flow = activeFlowConfig.flows[id];
    }
    if (!flow) {
        return null;
    }
    var result = {
        id: id
    };
    if (flow.label) {
        result.label = flow.label;
    }
    if (flow.hasOwnProperty('disabled')) {
        result.disabled = flow.disabled;
    }
    if (flow.hasOwnProperty('info')) {
        result.info = flow.info;
    }
    if (flow.hasOwnProperty('env')) {
        result.env = flow.env;
    }
    copyFlowLayoutProperties(flow, result);
    if (id !== 'global') {
        result.nodes = [];
    }

    if (flow.groups) {
        var nodeIds = Object.keys(flow.groups);
        if (nodeIds.length > 0) {
            nodeIds.forEach(function(nodeId) {
                var node = jsonClone(flow.groups[nodeId]);
                delete node.credentials;
                result.nodes.push(node)
            })
        }
    }
    if (flow.nodes) {
        var nodeIds = Object.keys(flow.nodes);
        if (nodeIds.length > 0) {
            nodeIds.forEach(function(nodeId) {
                var node = jsonClone(flow.nodes[nodeId]);
                if (node.type === 'link out') {
                    delete node.wires;
                }
                delete node.credentials;
                result.nodes.push(node)
            })
        }
    }
    if (flow.configs) {
        var configIds = Object.keys(flow.configs);
        result.configs = configIds.map(function(configId) {
            const node = jsonClone(flow.configs[configId]);
            delete node.credentials;
            return node

        })
        if (result.configs.length === 0) {
            delete result.configs;
        }
    }
    if (flow.subflows) {
        var subflowIds = Object.keys(flow.subflows);
        result.subflows = subflowIds.map(function(subflowId) {
            var subflow = jsonClone(flow.subflows[subflowId]);
            var nodeIds = Object.keys(subflow.nodes);
            subflow.nodes = nodeIds.map(function(id) {
                const node = jsonClone(subflow.nodes[id])
                delete node.credentials
                return node
            });
            if (subflow.groups) {
                var nodeIds = Object.keys(subflow.groups);
                if (nodeIds.length > 0) {
                    nodeIds.forEach(function(nodeId) {
                        var node = jsonClone(subflow.groups[nodeId]);
                        delete node.credentials;
                        subflow.nodes.push(node)
                    })
                }
                delete subflow.groups
            }
            if (subflow.configs) {
                var configIds = Object.keys(subflow.configs);
                subflow.configs = configIds.map(function(id) {
                    const node = jsonClone(subflow.configs[id])
                    delete node.credentials
                    return node
                })
            }
            delete subflow.instances;
            return subflow;
        });
        if (result.subflows.length === 0) {
            delete result.subflows;
        }
    }
    return result;
}

/**
 * Builds the full configuration that replaces flow `id` (or, for `global`, the
 * global configuration nodes and subflows) with `newFlow`
 * (E-01: the configuration deployed by updateFlow, without deploying it).
 * Sets `z` of the new nodes, as updateFlow does.
 * @param {String} id - the flow id, or "global"
 * @param {Object} newFlow - the flow
 * @param {Object} [opts]
 * @param {boolean} [opts.create] - create the flow under `id` if it does not exist (Z-04)
 * @param {Array} [opts.globalConfigs] - global configuration nodes to add or replace (Z-04)
 * @return {{config: Array, label: String, created: boolean}} - the new configuration, the
 *     label used in the log and whether the flow is created
 * @throws {Error} with `code` 404 if the flow does not exist (without `opts.create`);
 *     "invalid_flow_id" when `id` is used by another node; "duplicate_id" when a node id
 *     is used in another flow (Z-04); "invalid_node_type" for globalConfigs
 */
function buildUpdateFlowConfig(id, newFlow, opts) {
    opts = opts || {};
    var label = id;
    var created = false;
    if (id !== 'global') {
        if (!activeFlowConfig.flows[id]) {
            if (!opts.create) {
                var e = new Error();
                e.code = 404;
                throw e;
            }
            if (activeConfig.flows.some(n => n.id === id)) {
                throw flowError("invalid_flow_id", "invalid flow id: "+id+" is used by another node");
            }
            created = true;
            label = newFlow.label;
        } else {
            label = activeFlowConfig.flows[id].label;
        }
    }
    var newConfig = jsonClone(activeConfig.flows);
    var nodes;

    if (id === 'global') {
        // Remove all nodes whose z is not a known flow
        // When subflows can be owned by a flow, this logic will have to take
        // that into account
        newConfig = newConfig.filter(function(node) {
            return node.type === 'tab' || (node.hasOwnProperty('z') && activeFlowConfig.flows.hasOwnProperty(node.z));
        })

        // Add in the new config nodes
        nodes = newFlow.configs||[];
        if (newFlow.subflows) {
            // Add in the new subflows
            newFlow.subflows.forEach(function(sf) {
                nodes = nodes.concat(sf.nodes||[]).concat(sf.configs||[]);
                delete sf.nodes;
                delete sf.configs;
                nodes.push(sf);
            });
        }
    } else {
        newConfig = newConfig.filter(function(node) {
            return node.z !== id && node.id !== id;
        });
        var tabNode = buildTabNode(id, newFlow);
        if (newFlow.hasOwnProperty('credentials')) {
            tabNode.credentials = newFlow.credentials;
        }

        nodes = [tabNode].concat(newFlow.nodes||[]).concat(newFlow.configs||[]);
        // Z-04: the nodes of the flow must not use ids of other flows or of
        // global nodes (not checked before)
        const otherIds = {};
        newConfig.forEach(function(n) { otherIds[n.id] = n.z || n.id });
        nodes.forEach(function(n) {
            if (n.type !== 'tab' && otherIds[n.id]) {
                throw flowError("duplicate_id", "duplicate id: "+n.id+" is used in flow "+otherIds[n.id]);
            }
        });
        nodes.forEach(function(n) {
            if (n.type !== 'tab') {
                n.z = id;
            }
        });
    }

    newConfig = newConfig.concat(nodes);
    if (opts.globalConfigs) {
        newConfig = applyGlobalConfigs(newConfig, opts.globalConfigs);
    }
    return { config: newConfig, label: label, created: created };
}

async function updateFlow(id,newFlow, user, deployOpts, opts) {
    var built = buildUpdateFlowConfig(id, newFlow, opts);
    var label = built.label;
    return setFlows(built.config, null, 'flows', true, null, user, deployOpts).then(function() {
        log.info(log._("nodes.flows.updated-flow",{label:(label?label+" ":"")+"["+id+"]"}));
        // Z-04: whether the flow was created (deploy.putCreatesFlow)
        return { created: built.created };
    })
}

/**
 * Builds the full configuration without flow `id`
 * (E-01: the configuration deployed by removeFlow, without deploying it).
 * @param {String} id - the flow id
 * @return {{config: Array, flow: Object}} - the new configuration and the removed flow
 * @throws {Error} for "global"; with `code` 404 if the flow does not exist
 */
function buildRemoveFlowConfig(id) {
    if (id === 'global') {
        // TODO: nls + error code
        throw new Error('not allowed to remove global');
    }
    var flow = activeFlowConfig.flows[id];
    if (!flow) {
        var e = new Error();
        e.code = 404;
        throw e;
    }

    var newConfig = jsonClone(activeConfig.flows);
    newConfig = newConfig.filter(function(node) {
        return node.z !== id && node.id !== id;
    });
    return { config: newConfig, flow: flow };
}

async function removeFlow(id, user, deployOpts) {
    var built = buildRemoveFlowConfig(id);
    var flow = built.flow;
    return setFlows(built.config, null, 'flows', true, null, user, deployOpts).then(function() {
        log.info(log._("nodes.flows.removed-flow",{label:(flow.label?flow.label+" ":"")+"["+flow.id+"]"}));
    });
}

const flowAPI = {
    getNode: getNode,
    handleError: () => false,
    handleStatus: () => false,
    getSetting: k => flowUtil.getEnvVar(k),
    log: m => log.log(m)
}

module.exports = {
    init: init,

    /**
     * Load the current flow configuration from storage
     * @return a promise for the loading of the config
     */
    load: load,
    loadFlows: load,

    /**
     * Read the flow configuration from storage, without deploying it (E-01)
     * @return a promise for the configuration
     */
    readFlowsFromStorage: readFlowsFromStorage,
    reloadFromStorage: reloadFromStorage,
    getChangedFlows: getChangedFlows,
    isEditorOnly: isEditorOnly,

    get:getNode,
    eachNode: eachNode,
  
    /**
     * Gets the current flow configuration
     */
    getFlows: getFlows,

    /**
     * Sets the current active config.
     * @param config the configuration to enable
     * @param type the type of deployment to do: full (default), nodes, flows, load
     * @return a promise for the saving/starting of the new flow
     */
    setFlows: setFlows,

    /**
     * Starts the current flow configuration
     */
    startFlows: start,

    /**
     * Stops the current flow configuration
     * @return a promise for the stopping of the flow
     */
    stopFlows: stop,

    get started() { return started },
    state: () => { return state },
    // handleError: handleError,
    // handleStatus: handleStatus,

    checkTypeInUse: checkTypeInUse,

    addFlow: addFlow,
    getFlow: getFlow,
    updateFlow: updateFlow,
    removeFlow: removeFlow,
    getFlowRevision: getFlowRevision,
    buildAddFlowConfig: buildAddFlowConfig,
    buildUpdateFlowConfig: buildUpdateFlowConfig,
    buildRemoveFlowConfig: buildRemoveFlowConfig,
    disableFlow:null,
    enableFlow:null,
    isDeliveryModeAsync: function() {
        // If settings is null, this is likely being run by unit tests
        return !settings || !settings.runtimeSyncDelivery
    }

};
